  "Traduce texto, documentos y adjuntos de Zotero con el modelo que elijas, incluido un modo PDF facsímil.": "使用你選擇的模型翻譯文本、文件和Zotero附件，包括PDF影印模式。",
  "Traducir texto, documentos y adjuntos de Zotero con el modelo elegido, conservando la estructura de DOCX y EPUB y la apariencia de los PDF mediante un modo facsímil.": "使用所選模型翻譯文本、文件和Zotero附件，保留DOCX和EPUB的結構，並通過影印模式保留PDF的外觀。",
  "Mover documento a la papelera": "將文件移到廢紙簍",
  "Mover documentos a la papelera": "將文件移到廢紙簍",
  "«{name}» dejará de aparecer. Podrás recuperarlo desde la administración de datos.": "「{name}」將不再顯示。你可以從資料管理中恢復它。",
  "Los {n} documentos seleccionados dejarán de aparecer. Podrás recuperarlos desde la administración de datos.": "所選的{n}個文件將不再顯示。你可以從資料管理中恢復它們。",
  "¿Eliminar también las ideas vinculadas?": "是否一併刪除關聯的觀點？",
  "Se eliminarán las ideas que solo proceden de estos documentos, junto con sus embeddings, evidencia y conexiones. Las ideas compartidas con otras fuentes se conservarán.": "僅來自這些文件的觀點將被刪除，連同其嵌入、證據和連線。與其他來源共享的觀點會保留。",
  "Eliminar ideas y embeddings": "刪除觀點和嵌入",
  "Conservar ideas": "保留觀點",
  "Cancelar operación": "取消操作",
  "Eliminar idea": "刪除觀點",
  "Se eliminará «{name}» junto con su embedding, evidencia y conexiones. Esta acción no se puede deshacer.": "「{name}」將被刪除，連同其嵌入、證據和連線。此操作無法撤銷。",
  "Seleccionar o desplazar": "選擇或滾動",
  "Editar o eliminar": "編輯或刪除",
  "Suelta los archivos para añadirlos a esta sección": "拖放檔案以將其新增到本節",
  "Se importarán como materiales en la selección actual.": "它們將作為材料匯入當前選擇中。",
  "No se pudo traducir este mensaje.": "無法翻譯此訊息。",
  "Analizando fragmento {current}/{total} con IA… ({seconds}s)": "正在使用AI分析片段 {current}/{total}…（{seconds}s）",
  "Analizando fragmento {current}/{total} con IA…": "正在使用AI分析片段 {current}/{total}…",
  "Fusionando idea {current}/{total}…": "正在合併觀點 {current}/{total}…",
