  "{candidates} candidatos encontrados ({cross} entre temas)": "找到{candidates}個候選（{cross}個跨主題）",
  "{n} nuevas relaciones": "{n}條新關係",
  "{added} nuevas · {validated} validados · {scanned} escaneados": "{added}條新增 · {validated}條已驗證 · {scanned}條已掃描",
  "Reintentando ({current}/{total})…": "正在重試（{current}/{total}）…",
  "Lecturas fundamentales": "基礎閱讀",
  "Base conceptual y dependencias intelectuales que conviene leer antes de avanzar.": "在推進之前宜先閱讀的概念基礎與思想脈絡。",
  "Textos más útiles para cubrir o delimitar huecos detectados en el corpus.": "用於填補或界定語料庫中所發現空白的最有用文本。",
  "Ampliación de temas secundarios": "擴充套件次要主題",
  "Lecturas que amplían temas del proyecto sin saturar una sola línea temática.": "擴充套件專案主題而不使單一研究主線過載的閱讀。",
  "Contrastar ideas o contradicciones": "對比觀點或矛盾",
