  "Obras marcadas como leídas en Zotero pero todavía sin análisis profundo suficiente.": "在Zotero中標記為已讀但深度分析仍不充分的文獻。",
  "Siguientes mejores opciones": "次優選擇",
  "Lecturas restantes que todavía aportan señales relevantes para el criterio elegido.": "仍能為所選標準提供相關訊號的其餘閱讀。",
