  "Ponle un título a la rúbrica.": "為評分標準設定標題。",
  "Una rúbrica necesita al menos dos niveles de desempeño.": "評分標準至少需要兩個表現等級。",
  "Añade al menos un criterio de evaluación.": "至少新增一個評價標準。",
  "Cada nivel necesita un nombre.": "每個等級都需要一個名稱。",
  "Cada criterio necesita un nombre.": "每個標準都需要一個名稱。",
  "Hay niveles con la misma puntuación: no se podrán distinguir al calificar.": "有些等級得分相同：評分時將無法區分。",
  "Este criterio no tiene ningún descriptor escrito.": "此標準沒有寫任何描述符。",
  "Faltan descriptores en algunos niveles de este criterio.": "此標準的某些等級缺少描述符。",
  "Los pesos de los criterios no suman 100 %.": "各標準的權重之和不為 100%。",
  "Con más de 6 criterios la rúbrica se vuelve difícil de aplicar en clase.": "標準超過 6 個時，評分標準在課堂上會難以應用。",
  "Más de 5 niveles aparenta una precisión que no se sostiene al corregir.": "超過 5 個等級會顯得精確，但批改時站不住腳。",
  "Este criterio parece un requisito de entrega, no una cualidad del trabajo.": "此標準看起來像是提交要求，而不是作業的品質。",
  "Este criterio junta dos aspectos: sepáralos para poder evaluarlos por separado.": "此標準將兩個方面合併在一起：請將它們分開，以便分別評價。",
  "Este descriptor solo emite un juicio: describe qué hace el trabajo.": "此描述符只作出評判：請描述作業實際做了什麼。",
  "Este descriptor describe carencias: redáctalo en positivo, por lo que el trabajo sí hace.": "此描述符只描述不足之處：請圍繞作業確實做到的方面，以正面方式撰寫。",
  "Estos dos niveles solo se diferencian en matices: ¿qué hace distinto el trabajo?": "這兩個等級僅在細微之處有差別：作業有哪些不同的表現？",
  "Dos niveles repiten el mismo descriptor.": "兩個等級重複了同一描述符。",
  "Los descriptores de este criterio tienen longitudes muy dispares: mantén una estructura paralela.": "此標準的各描述符長度差異很大：請保持平行的結構。",
  "Las puntuaciones no descienden de mayor a menor desempeño.": "分數沒有從最高表現等級向最低遞減。",
  "Crea rúbricas de evaluación por criterios y niveles, con ayuda de la IA.": "藉助 AI，按標準和等級建立評價評分標準。",
