  "Este vault es una preview navegable: se creará normalmente, pero por ahora sus secciones son solo una muestra y no permiten realizar acciones.": "該知識庫是可導航的預覽：它會正常建立，但目前其版塊僅為展示，無法執行操作。",
  "Este vault muestra la estructura prevista. Sus secciones todavía no permiten realizar acciones.": "該知識庫展示的是計劃結構。其版塊目前仍無法執行操作。",
