  "Paletas de color. El modo claro u oscuro se ajusta arriba.": "配色方案。淺色或深色模式在上方設定。",
  "Usar la misma paleta en todas las bóvedas": "在所有知識庫中使用相同的調色盤",
  "Activado, todas las bóvedas comparten la paleta. Desactivado, cada una recuerda la suya y las nuevas empiezan con la predeterminada. El modo claro u oscuro es común en ambos casos.": "開啟後，所有知識庫共用同一調色盤。關閉後，每個知識庫保留自己的調色盤，新建知識庫從預設調色盤開始。淺色或深色模式在兩種情況下都共用。",
  "Paleta de la bóveda": "知識庫調色盤",
  "Crear tema": "建立主題",
  "Editar tema": "編輯主題",
  "Guardar tema": "儲存主題",
  "Mi tema": "我的主題",
  "Nombre del tema personalizado": "自定義主題名稱",
  "Hexadecimal": "十六進位制",
  "Acento": "強調色",
  "Superficie clara": "淺色表面",
