  "Modelo predeterminado ({n} disponibles)": "預設模型（{n} 個可用）",
  "Podrás añadir más proveedores y marcar favoritos en Ajustes.": "你可以在設定中新增更多提供商並標記收藏。",
  "⚠ Sin un modelo seleccionado podrás sincronizar metadatos, pero no analizar temas ni ideas hasta configurarlo.": "⚠ 未選擇模型時，你可以同步後設資料，但在配置之前無法分析主題或觀點。",
  "Sincronizando Zotero para preparar el panel inicial...": "正在同步 Zotero 以準備初始面板…",
  "No se pudo completar la primera sincronización, pero puedes entrar y corregirlo desde Inicio o Ajustes.": "首次同步未能完成，但你可以進入，並從首頁或設定中修復。",
  "La biblioteca local ya está preparada. El panel de Inicio te dirá qué conviene hacer después.": "本地文獻庫已準備好。首頁面板會告訴你接下來該做什麼。",
