  "storage no configurado": "未配置儲存",
  "La sincronización puede funcionar, pero Nodus necesita un modelo predeterminado para extraer temas, ideas y evidencias.": "同步可以執行，但Nodus需要預設模型來提取主題、觀點和證據。",
  "Sincroniza Zotero para crear el corpus": "同步Zotero以建立語料庫",
  "Todavía no hay obras locales. Revisa las colecciones monitorizadas y ejecuta una sincronización para poblar la biblioteca.": "尚無本地文獻。請檢查監控的集合，並執行同步以填充文獻庫。",
  "Sincronizar ahora": "立即同步",
  "Completa el análisis ligero": "完成輕量分析",
  "El primer resultado visible del mapa depende de los temas extraídos a partir de título y resumen. Analiza temas antes de profundizar.": "圖譜的首個可見結果取決於從標題和摘要中提取的主題。請先分析主題再深入。",
  "Analizar temas": "分析主題",
