  "El grafo ya puede orientarte por temas; el siguiente salto de valor llega al analizar a fondo las obras leídas o seleccionadas.": "圖譜已可按主題為你指引方向；下一個價值躍升來自對已讀或所選文獻的深度分析。",
  "Analizar ideas": "分析觀點",
