  "Hay ideas extraídas sin índice semántico. Indexarlas mejora la fusión, las relaciones y el descubrimiento de puentes.": "有已提取的觀點尚無語義索引。為其建立索引可改善融合、關係和橋梁發現。",
  "Ver ideas": "檢視觀點",
  "Convierte el grafo en escritura": "將圖譜轉化為寫作",
  "Ya hay suficientes ideas y fuentes para montar un estado de la cuestión, un marco teórico o una justificación de hueco con citas verificables.": "已有足夠的觀點和資料來撰寫文獻綜述、理論框架或空白論證，並附可驗證的引注。",
  "Abrir taller": "開啟工作臺",
  "Ver huecos": "檢視空白",
  "Revisa huecos y contradicciones": "檢查空白與矛盾",
  "El corpus ya tiene material interpretativo. El siguiente paso útil es convertir huecos y tensiones en una ruta de lectura o pregunta de investigación.": "語料庫已有可解讀的素材。下一步有用的做法是將空白與張力轉化為閱讀路徑或研究問題。",
  "Explora el grafo con el Tutor": "與導師一起探索圖譜",
  "El corpus está en buen estado para una lectura guiada. Abre el grafo o pregunta al asistente con el contexto completo.": "語料庫狀態良好，適合進行引導式閱讀。請開啟圖譜，或帶著完整上下文向助手提問。",
  "ligero": "輕量",
  "profundo": "深度",
  "Sin texto disponible": "無可用文本",
  "sin texto": "無文本",
