  "{n} obras visibles": "{n}篇可見文獻",
  "Operaciones": "操作",
  "Buscar título o autor…": "搜尋標題或作者…",
  "Ligero: todos": "輕量：全部",
  "Ligero: ninguno": "輕量：無",
  "Ligero: hecho": "輕量：已完成",
  "Ligero: pendiente": "輕量：待處理",
  "Ligero: fallido": "輕量：失敗",
  "Profundo: todos": "深度：全部",
