  "Temas principales": "主要主題",
  "Los temas principales son los grandes nodos que agrupan tus ideas en el grafo. Añade los tuyos para controlarlos manualmente; mientras estén bloqueados, los análisis solo usarán estos temas y no generarán otros nuevos.": "主要主題是圖譜中聚合觀點的較大節點。新增你自己的主題以手動控制它們；鎖定期間，分析只會使用這些主題，不會生成新的主題。",
  "coge las ideas ya extraídas (afirmaciones, hallazgos…) y las vuelve a agrupar bajo estos temas con el modelo seleccionado, sin volver a leer los documentos ni re-extraer ideas.": "會獲取已提取的觀點（論斷、發現…），並用所選模型將它們重新歸入這些主題下，無需重新閱讀文件或重新提取觀點。",
