  "Guardados": "已儲存",
  "Una IA de contexto largo analiza todas tus ideas, temas y conexiones y traza un recorrido guiado. Avanza con las flechas y el Tutor te lo explica paso a paso sobre el propio grafo.": "長上下文 AI 會分析你的所有觀點、主題和連線，並繪製一條引導路線。使用箭頭前進，導師會在圖譜上逐步為你講解。",
  "Tipo de recorrido": "路線型別",
  "Recorrido completo": "完整路線",
  "El Tutor propone varias rutas que cubren todo el grafo, ordenadas por peso, y menciona todo lo importante.": "導師會提出多條覆蓋整個圖譜的路線，按權重排序，並提及所有重要內容。",
  "Desde un objetivo": "從目標出發",
  "Describe qué quieres repasar y el Tutor traza un recorrido a medida con las ideas y conexiones pertinentes.": "描述你想複習的內容，導師會結合相關觀點和關係為你規劃一條量身定製的路線。",
