  "Dame una síntesis crítica del corpus: ideas principales, contradicciones, huecos y próximos pasos.": "對語料庫做一份批判性綜述：主要觀點、矛盾、空白和後續步驟。",
  "Preguntas abiertas, limitaciones y trabajo futuro.": "開放性問題、侷限性和未來工作。",
  "Prioriza los huecos de investigación del corpus y propón cómo atacarlos con lecturas o análisis.": "優先梳理語料庫的研究空白，並提出如何通過閱讀或分析加以解決。",
