  "Resume las contradicciones más relevantes y distingue tensiones reales de diferencias de marco o método.": "總結最相關的矛盾，並區分真實張力與框架或方法上的差異。",
  "Ruta de lectura, documentos, autores y grafo completo.": "閱讀路徑、文件、作者和完整圖譜。",
