  "Aún no hay informes. Crea el primero y quedará aquí, listo para leerse a pantalla completa.": "還沒有報告。建立第一份，它會留在這裡，可全屏閱讀。",
  "Cola de generación · {n} en curso": "生成佇列 · {n} 進行中",
