  "Quitar de la cola": "從佇列中移除",
  "No se pudo quitar el informe de la cola.": "無法從佇列中移除該報告。",
  "Falló": "失敗",
  "Abrir a pantalla completa": "全屏開啟",
  "Reutilizar la idea para un informe nuevo": "複用該觀點建立新報告",
  "El informe desarrolla tu idea por completo, citando todo el corpus.": "報告會完整展開你的觀點，並引用整個語料庫。",
  "Se añadirá a la cola ({n} en curso) y se generará cuando termine el anterior.": "將新增到佇列（{n} 進行中），並在前一個完成後生成。",
  "Se genera en segundo plano: puedes cerrar esto y seguir trabajando.": "在後臺生成：你可以關閉此處並繼續工作。",
  "Añadir a la cola": "新增到佇列",
  "Informe añadido a la cola. Se generará en segundo plano.": "報告已新增到佇列，將在後臺生成。",
  "Pulsa «Nuevo informe» y escribe la pregunta o idea. El informe la convierte en un texto de varias páginas, no en una respuesta corta.": "點選「新建報告」並寫下問題或觀點。報告會將其轉化為多頁文本，而不是簡短回答。",
  "Añade varios informes a la cola: se generan en cadena, uno tras otro, mientras sigues trabajando.": "可將多份報告加入佇列：它們會依次生成，你可以繼續工作。",
  "Abre cualquier informe de la galería para leerlo a pantalla completa, revisar sus citas y exportarlo a Markdown o PDF.": "開啟庫中的任意報告即可全屏閱讀、檢視引注，並匯出為 Markdown 或 PDF。",
  "Taller": "工坊",
  "Informe guardado localmente.": "報告已儲存到本地。",
  "Informe guardado abierto. Puedes exportarlo o reutilizar su idea para regenerarlo.": "已開啟儲存的報告。你可以匯出它，或複用其觀點重新生成。",
  "Idea reutilizada: ajusta los parámetros y genera un informe actualizado.": "已複用觀點：調整引數並生成更新後的報告。",
  "¿Eliminar este informe guardado? Esta acción no se puede deshacer.": "要刪除這份已儲存的報告嗎？此操作無法撤銷。",
  "Informe eliminado.": "報告已刪除。",
  "Escribe la pregunta o idea de investigación que quieres desarrollar. El informe la convierte en un texto de varias páginas, no en una respuesta corta.": "寫下你想展開的研究問題或觀點。報告會將其轉化為多頁文本，而不是簡短回答。",
  "2. Ajusta el alcance": "2. 調整範圍",
  "Elige la extensión objetivo y el número máximo de secciones. Menos secciones producen un texto más profundo; más secciones, uno más panorámico.": "選擇目標篇幅和最大分節數。分節越少，文本越深入；分節越多，視野越全面。",
  "Nodus recorre todo el corpus indexado, planifica las secciones y redacta guiado por la cobertura, citando cada obra sin que tengas que seleccionarla.": "Nodus 會遍歷整個已索引的語料庫，規劃分節，並在覆蓋度引導下撰寫，自動引用每篇文獻，無需你手動選擇。",
  "4. Revisa y exporta": "4. 檢查並匯出",
  "Abre las citas para comprobar cada fuente, guarda el informe para retomarlo y expórtalo a Markdown o PDF cuando esté listo.": "開啟引注核對每個來源，儲存報告以便日後繼續，準備就緒後匯出為 Markdown 或 PDF。",
  "Informe académico de varias páginas, guiado por cobertura y con todas las fuentes citadas.": "多頁學術報告，以覆蓋度為引導，並引用全部來源。",
  "Adaptativo (según corpus)": "自適應（依據語料庫）",
  "Conciso (5–8 pág.)": "簡潔（5–8 頁）",
  "Estándar (9–14 pág.)": "標準（9–14 頁）",
  "Exhaustivo (15–20 pág.)": "詳盡（15–20 頁）",
  "Extensión objetivo del informe": "報告目標篇幅",
  "Extensión:": "篇幅：",
  "Secciones:": "分節：",
  "Número máximo de secciones (menos secciones = mayor profundidad)": "最大分節數（分節越少 = 越深入）",
  "Secciones: Auto (IA decide)": "分節：自動（由 AI 決定）",
  "Bloque único · sin secciones": "單一整塊 · 無分節",
  "Estructura del informe": "報告結構",
  "Una narración continua sin encabezados internos; conserva toda la recuperación y el análisis.": "一段連續的敘述，無內部標題；保留全部檢索和分析。",
  "El esquema manual fija exactamente las partes y su orden.": "手動大綱會精確固定各部分及其順序。",
  "La estructura organiza el informe, pero nunca limita la evidencia relevante.": "結構用於組織報告，但絕不限制相關證據。",
  "Secciones: Auto": "分節：自動",
