  "No se pudo generar el informe.": "無法生成報告。",
  "Escribe la idea de investigación antes de generar el informe.": "生成報告前請先寫下研究觀點。",
  "Escribe la idea o pregunta de investigación. El informe la desarrollará por completo, citando todas las obras del corpus.": "寫下研究觀點或問題。報告會將其完整展開，並引用語料庫中的所有文獻。",
  "Cobertura del corpus completo": "全語料庫覆蓋",
  "Sin selección manual: el informe elige y cita las fuentes por ti.": "無需手動選擇：報告會替你挑選並引用來源。",
  "Puedes cambiar de sección: el informe seguirá en segundo plano y recuperarás este progreso al volver.": "你可以切換分節：報告將在後臺繼續，返回時可恢復此進度。",
  "Informe generado: {s} secciones · ~{p} páginas · {i} ideas citadas.": "報告已生成：{s} 個分節 · 約 {p} 頁 · 引用 {i} 個觀點。",
  "Informe generado y guardado: {s} secciones · ~{p} páginas · {i} ideas citadas.": "報告已生成並儲存：{s} 個分節 · 約 {p} 頁 · 引用 {i} 個觀點。",
  "Informe generado, pero no se pudo guardar automáticamente: {error}": "報告已生成，但無法自動儲存：{error}",
  "El informe está listo y puedes guardarlo manualmente.": "報告已就緒，你可以手動儲存。",
  "El informe aparecerá aquí. Escribe tu idea de investigación y pulsa «Generar informe».": "報告將顯示在這裡。寫下你的研究觀點，然後點選「生成報告」。",
  "Planifica, redacta sección a sección guiado por la cobertura del corpus y ensambla un informe académico de 5–20 páginas con todas las fuentes citadas.": "在語料庫覆蓋度的引導下規劃並逐節撰寫，最終彙編成一份 5–20 頁、引用全部來源的學術報告。",
