  "1. Delimita": "1. 明確範圍",
  "Escribe el apartado que quieres construir: pregunta, capítulo, debate, hueco o marco teórico. Cuanto más concreto sea el objetivo, mejor se ordena la mesa.": "寫下你想構建的章節：問題、章、討論、空白或理論框架。目標越具體，工作臺組織得越好。",
  "2. Monta la mesa": "2. 搭建工作臺",
  "Pulsa Preparar mesa y revisa ideas, temas, huecos, contradicciones, obras y rutas. Usa Todas las ideas cuando quieras una revisión amplia del corpus encontrado.": "點選「準備工作臺」，檢視觀點、主題、空白、矛盾、文獻和路線。想要廣泛審視已找到的語料庫時，使用「所有觀點」。",
  "3. Decide el foco": "3. 確定重點",
  "Selecciona todo para explorar, vacía para empezar de cero o ajusta cada pestaña. La matriz final te dirá qué papel cumple cada material en el argumento.": "全選以探索，清空以從零開始，或逐一調整每個標籤頁。最終矩陣會告訴你每份材料在論證中的作用。",
  "4. Convierte en texto": "4. 轉化為文本",
  "Genera el borrador, abre las citas para verificar fuentes, guárdalo si quieres retomarlo y exporta Markdown cuando el hilo argumental ya tenga sentido para tu manuscrito.": "生成草稿，開啟引注核對來源，如需日後繼續可先儲存，當論證脈絡適合你的手稿時匯出 Markdown。",
  "curado": "已整理",
  "analizada": "已分析",
  "Toda la red de ideas y temas.": "全部觀點與主題構成的網路。",
