  "Marcadas como leídas o seleccionadas, pero todavía sin ideas extraídas.": "已標記為已讀或已選中，但尚未提取觀點。",
  "Profundiza {n} obra(s) con solo análisis ligero": "深入分析 {n} 篇僅有輕度分析的文獻",
  "Tienen temas pero aún no ideas; son las candidatas naturales al análisis profundo.": "它們已有主題但尚無觀點，是深度分析的天然候選。",
  "Indexa {n} idea(s) sin embedding": "為 {n} 個無嵌入的觀點建立索引",
  "La búsqueda por significado, la fusión y los puentes dependen del índice semántico.": "語義搜尋、融合與橋接都依賴語義索引。",
  "Indexa pasajes de {n} obra(s) con texto": "為 {n} 篇有文本的文獻索引片段",
  "Sin pasajes no hay búsqueda semántica de evidencia ni citas a nivel de fragmento.": "沒有片段，就無法進行證據的語義搜尋，也無法實現片段級引用。",
