  "Proyecto listo para revisar, exportar o cerrar.": "專案已可審閱、匯出或關閉。",
  "Brief y pregunta": "簡報與問題",
  "Objetivo, alcance y criterio de lectura definidos.": "已定義目標、範圍和閱讀標準。",
  "Pregunta y cobertura": "問題與覆蓋範圍",
