  "Obras, ideas, notas, huecos o borradores listos para integrarse.": "可整合的文獻、觀點、筆記、空白或草稿。",
  "Debates, huecos y borradores organizados antes de intervenir el texto.": "在修改文本之前，先整理好討論、空白與草稿。",
  "Manuscrito": "手稿",
  "Capítulo o artículo importado como texto editable y versionado.": "以可編輯、可版本化的文本匯入的章節或文章。",
  "Revisión y salida": "審閱與輸出",
  "Relaciones, sugerencias verificables y exportación final.": "關係、可驗證建議與最終匯出。",
  "Marcar cobertura": "標記覆蓋範圍",
