  "Objetivo, alcance, pregunta principal y criterio de selección": "目標、範圍、主要問題與選擇標準",
  "Brief actualizado. El flujo guiado ya usa este objetivo.": "簡報已更新。引導流程現已使用此目標。",
  "Cobertura marcada como en curso.": "覆蓋範圍已標記為進行中。",
  "Materiales preparados para el estado de la cuestión.": "已為文獻綜述準備好材料。",
  "Estructura argumental preparada.": "論證結構已準備就緒。",
  "No se encontraron nuevas sugerencias verificables para este capítulo.": "未發現此章節新的可驗證建議。",
  "Define el objetivo, el alcance, la pregunta principal y el criterio de selección de fuentes. Este texto aparece en la cabecera del proyecto, se envía como contexto a la IA al generar sugerencias y se incluye en la exportación.": "定義目標、範圍、主要問題與資料來源選擇標準。此文本會顯示在專案頁首中，在生成建議時作為上下文傳送給 AI，並包含在匯出內容中。",
  "Vincula tu pregunta de investigación con el corpus: indica qué áreas ya están cubiertas y qué falta por explorar. Marcar este paso como en curso activa la sección de cobertura en el proyecto.": "將你的研究問題與語料庫關聯起來：說明哪些領域已被覆蓋、哪些尚待探索。將此步驟標記為進行中會啟用專案中的覆蓋範圍部分。",
  "Añade obras, ideas, notas, huecos, debates y borradores al proyecto. Estos materiales son los que la IA usará para proponer inserciones con citas verificables en el manuscrito.": "向專案新增文獻、觀點、筆記、空白、討論與草稿。AI 將使用這些材料，在手稿中提出帶有可驗證引用的插入建議。",
  "Organiza los debates, huecos y borradores que estructurarán el argumento antes de redactar los capítulos. Puedes activar cada bloque por separado para marcar que está listo para usarse.": "在撰寫各章節之前，整理好將構成論證的討論、空白與草稿。你可以單獨啟用每個模組，以標記其可供使用。",
  "Importa un capítulo o artículo como texto editable. Nodus lo versiona automáticamente y permite aplicar sugerencias sobre el borrador.": "將章節或文章匯入為可編輯文本。Nodus 會自動為其建立版本，並允許在草稿上應用建議。",
  "Genera sugerencias verificables contra el corpus y revisa las citas del manuscrito antes de exportar o cerrar el proyecto.": "根據語料庫生成可驗證建議，並在匯出或關閉專案之前審閱手稿中的引用。",
