  "Extrae las ideas de este capítulo (no se añaden al grafo) y busca cómo se relacionan con tu biblioteca: ideas, notas, pasajes y obras.": "提取本章節的觀點（不會新增到圖譜），並查詢它們與你的文獻庫之間的關係：觀點、筆記、片段和文獻。",
  "Analiza las relaciones para ver cómo conecta este capítulo con toda tu biblioteca.": "分析關係，瞭解本章節如何與你的整個文獻庫相連。",
