  "No se pudo localizar la frase exacta en el borrador; insértala manualmente desde el texto.": "無法在草稿中定位到確切句子；請從文本中手動插入。",
  "Eliminar proyecto": "刪除專案",
  "Proyecto eliminado.": "專案已刪除。",
  "¿Eliminar el proyecto «{title}»? Se borrarán sus secciones, vínculos y capítulos. Las notas y carpetas creadas se conservan. Esta acción no se puede deshacer.": "確定要刪除專案「{title}」嗎？其各部分、關聯和章節將被刪除。已建立的筆記和資料夾會保留。此操作無法撤銷。",
