  "Ver y deshacer tus veredictos sobre relaciones (confirmadas y rechazadas)": "檢視並撤銷你對關係的判定（已確認和已拒絕）",
  "Aún no has auditado ninguna relación. Abre una arista en el grafo y usa «Confirmar» o «Marcar como incorrecta».": "你尚未稽核任何關係。在圖譜中開啟一條邊，並使用「確認」或「標記為錯誤」。",
  "Rechazadas (ocultas del grafo y de los análisis)": "已拒絕（從圖譜和分析中隱藏）",
