  "Has marcado esta relación como incorrecta: desaparecerá del grafo y de los análisis.": "你已將此外關係標記為錯誤：它將從圖譜和分析中消失。",
  "Marcar esta relación como verificada por ti": "將此外關係標記為經你驗證",
