  "Sincronización entre equipos": "多裝置同步",
  "Copias de seguridad automáticas": "自動備份",
  "Copias cifradas periódicas en una carpeta a tu elección. Cada copia incluye todo Nodus; puedes usar iCloud Drive, Google Drive o Dropbox para mantenerla fuera de este equipo.": "按你選擇的資料夾定期建立加密副本。每次備份都包含整個 Nodus；你可以使用 iCloud Drive、Google Drive 或 Dropbox 將其儲存在本機之外。",
  "Cada copia protege todo Nodus automáticamente.": "每次備份都會自動保護整個 Nodus。",
  "Incluye todas las bóvedas, documentos, preferencias, historiales, archivos generados y claves API. No existen exclusiones configurables.": "包含所有知識庫、文件、偏好設定、歷史記錄、生成的檔案和 API 金鑰。沒有可配置的排除項。",
  "Elegir carpeta": "選擇資料夾",
