  "Contraseña maestra configurada (guardada en el llavero del sistema).": "已配置主密碼（儲存在系統鑰匙串中）。",
  "Contraseña maestra y clave de recuperación configuradas.": "已配置主密碼和恢復金鑰。",
  "Guardar kit de recuperación": "儲存恢復工具包",
  "Cambiar contraseña": "更改密碼",
  "Contraseña maestra eliminada. Las copias automáticas quedan en pausa.": "主密碼已移除。自動備份已暫停。",
  "Contraseña maestra (mín. 8 caracteres)": "主密碼（至少 8 個字元）",
  "Guardar contraseña": "儲存密碼",
  "Contraseña maestra guardada. Descarga el kit de recuperación: sin la contraseña, las copias no se pueden restaurar.": "主密碼已儲存。請下載恢復工具包：沒有密碼，備份將無法恢復。",
  "Contraseña maestra guardada. Descarga el kit: permite recuperar incluso si olvidas la contraseña.": "主密碼已儲存。請下載工具包：即使忘記密碼也能恢復。",
  "Credenciales de recuperación de la copia": "備份恢復憑據",
  "Guarda ambas fuera de este dispositivo. Podrás importar la copia con cualquiera de ellas.": "請將兩者儲存在此裝置之外。使用其中任意一個即可匯入備份。",
  "Contraseña": "密碼",
