  "Quiero estudiar este autor como parte de mi corpus. Prioriza tesis, ideas, obras que debo abrir en Zotero, pasajes y contradicciones:": "我想將該作者作為語料庫的一部分來學習。請優先考慮論點、觀點、我應在 Zotero 中開啟的文獻、片段和矛盾之處：",
  "Modo Estudio: domina autores e ideas": "學習模式：掌握作者與觀點",
  "Cuando el objetivo sea aprender el corpus, entra en Estudio: Nodus prioriza autores, recomienda obras concretas para abrir en Zotero, propone sesiones tutor con pasajes y te permite marcar qué está entendido, qué queda en repaso y qué exige lectura completa.": "當目標是學習語料庫時，請進入學習模式：Nodus 會優先排列作者，推薦具體的文獻供在 Zotero 中開啟，提供帶片段的導師會話，並讓你標記哪些已掌握、哪些需要複習、哪些需要完整閱讀。",
