  "Carga un corpus de demostración de seis obras sobre la ciencia del aprendizaje. Podrás recorrer el grafo, ideas, debates, huecos y notas sin conectar Zotero ni configurar una clave de IA.": "載入一個包含六篇學習科學相關文獻的演示語料庫。無需連線 Zotero 或配置 AI 金鑰，即可瀏覽圖譜、觀點、爭論、空白和筆記。",
  "Cargar demo": "載入演示",
  "Explora con datos de ejemplo": "使用示例資料探索",
  "Prueba sin configurar nada": "無需任何配置即可試用",
  "Crea resúmenes de orientación independientes a partir de ideas, evidencia, temas y abstract. No son evidencia citable.": "基於觀點、證據、主題和原文摘要建立獨立的定位摘要。它們不是可引用的證據。",
  "El análisis profundo solo usó el abstract, no el texto completo (el PDF/EPUB no estaba disponible al analizar). Reanaliza cuando esté en Zotero.": "深度分析僅使用了原文摘要，未使用全文（分析時 PDF/EPUB 不可用）。待其加入 Zotero 後重新分析。",
  "El texto o el modelo de embeddings cambió.": "文本或嵌入模型已更改。",
  "Las ideas pertenecen a la versión anterior del texto. Vuelve a analizarlas para usar el texto actual.": "這些觀點屬於文本的舊版本。請重新分析以使用當前文本。",
  "El texto cambió; vuelve a indexar sus fragmentos.": "文本已更改；請重新索引其片段。",
  "Los fragmentos se indexaron con otro modelo de embeddings.": "這些片段是使用其他嵌入模型索引的。",
