  "Algunos fragmentos no tienen un embedding válido.": "部分片段沒有有效的嵌入。",
  "Generar resúmenes faltantes": "生成缺失的摘要",
  "Indexa fragmentos de texto completo en las obras que faltan o están obsoletas. No requiere análisis de ideas; el texto se mantiene como evidencia citable.": "為缺失或過期的文獻索引全文片段。無需分析觀點；文本仍作為可引用的證據。",
