  "Reanálisis en cola para {n} obra(s) «solo abstract». Verás el progreso en la cola.": "{n} 篇「僅原文摘要」文獻已加入重新分析佇列。你將在佇列中看到進度。",
  "Reanaliza las obras que solo se analizaron con el abstract (el PDF/EPUB no estaba disponible al analizarlas). Las que ya tengan el texto disponible en Zotero recuperarán el análisis completo; el resto se omiten sin coste. ¿Continuar?": "重新分析僅使用原文摘要分析的文獻（分析時 PDF/EPUB 不可用）。已在 Zotero 中有可用文本的文獻將恢復完整分析；其餘文獻將被跳過，不產生費用。是否繼續？",
  "Reanalizar": "重新分析",
  "Reanalizar «solo abstract»": "重新分析「僅原文摘要」",
  "Recorre toda la biblioteca y actualiza solo los índices que hayan cambiado. Los ya actuales se omiten.": "遍歷整個文獻庫，僅更新已更改的索引。已是最新的索引將被跳過。",
  "resumen": "摘要",
  "solo abstract": "僅原文摘要",
  "Vuelve a analizar las obras cuyo análisis profundo solo usó el abstract porque el PDF/EPUB no estaba disponible. Las que ya tengan el texto recuperan el análisis completo; el resto se omiten sin coste.": "重新分析那些因 PDF/EPUB 不可用而僅使用原文摘要進行深度分析的文獻。已有文本的文獻將恢復完整分析；其餘文獻將被跳過，不產生費用。",
