  "Sugerencias generadas. Algunas quedaron bloqueadas porque sus citas no son verificables.": "建議已生成。部分建議被阻止，因為其引用無法驗證。",
  "Sugerir ubicación": "建議位置",
  "Versión restaurada. Se guardó una copia previa antes de restaurar.": "版本已恢復。恢復前已儲存一份先前的副本。",
  "Resumen (orientación):": "摘要（概覽）：",
  "Pasajes de texto completo": "全文片段",
