  "Autor:": "作者：",
  "Datos de demostración eliminados.": "演示資料已刪除。",
  "Estás viendo un corpus de ejemplo. Sal del modo demo para empezar con tu propia biblioteca.": "你正在檢視示例語料庫。退出演示模式，開始使用你自己的文獻庫。",
  "Modelo de resúmenes (orientación por obra; no genera evidencia citable)": "摘要模型（按文獻概述；不生成可引用的證據）",
