  "Como los proveedores publican tamaños y métricas diferentes, la ordenación por precio se aplica por separado dentro de cada proveedor. Los modelos sin precio directo quedan al final; no se estiman costes.": "由於各提供商公佈的尺寸和指標不同，價格排序在每個提供商內部單獨應用。沒有直接價格的模型排在最後；不會估算費用。",
