  "Descripción de la escena": "場景描述",
  "Describe la escena que quieres ver. Si lo dejas vacío, se deduce del contenido.": "描述你想看到的場景。如果留空，將從內容中推斷。",
  "El estilo y las protecciones de «sin texto» se aplican automáticamente al generar.": "生成時會自動應用風格和「無文字」保護。",
