  "Cargado en memoria": "已載入到記憶體",
  "Ollama debe estar en marcha y los modelos descargados con \"ollama pull\". No requiere clave.": "Ollama 必須正在執行，並通過 \"ollama pull\" 下載模型。無需金鑰。",
  "Activa el servidor local en LM Studio (Developer → Start Server) y carga al menos un modelo. No requiere clave.": "在 LM Studio 中啟動本地伺服器（Developer → Start Server）並載入至少一個模型。無需金鑰。",
