  "El servidor no reporta modelos. Descarga o carga uno primero.": "伺服器未報告任何模型。請先下載或載入一個。",
  "Proveedor local: no necesita clave. Usa la dirección por defecto; puedes cambiar IP y puerto en Ajustes → Proveedores.": "本地提供商：無需金鑰。使用預設地址；可在設定 → 提供商中更改 IP 和埠。",
  "Traducciones con IA": "AI 翻譯",
  "Traduce este contenido a otro idioma. Cada idioma se guarda y puede regenerarse o eliminarse.": "將此內容翻譯為其他語言。每種語言都會被儲存，可重新生成或刪除。",
  "Traduciendo…": "正在翻譯…",
  "Genera la traducción con el modelo de IA configurado": "使用配置的 AI 模型生成翻譯",
  "La traducción de un texto largo puede tardar. Puedes cerrar esta ventana: se guardará y aparecerá aquí al volver.": "長文本的翻譯可能需要一些時間。你可以關閉此視窗：翻譯會被儲存，返回時會顯示在這裡。",
  "Cargando traducciones…": "正在載入翻譯…",
  "Aún no hay traducciones. Elige un idioma y genera la primera.": "還沒有翻譯。選擇一種語言並生成第一個。",
  "Regenerar esta traducción": "重新生成此翻譯",
  "Eliminar traducción": "刪除翻譯",
  "¿Eliminar la traducción a {lang}? Esta acción no se puede deshacer.": "刪除 {lang} 翻譯？此操作無法撤銷。",
  "Seleccionar todo": "全選",
