  "¿Eliminar {n} informes guardados? Esta acción no se puede deshacer.": "刪除 {n} 份已儲存的報告？此操作無法撤銷。",
  "{n} informes eliminados.": "已刪除 {n} 份報告。",
  "Eliminar inmersiones": "刪除沉浸",
  "¿Eliminar {n} inmersiones y todo su progreso? Esta acción no se puede deshacer.": "刪除 {n} 個沉浸及其全部進度？此操作無法撤銷。",
  "Nueva inmersión": "新建沉浸",
  "Domina un tema de tu corpus: panorama, estaciones con citas literales, contrastes, fronteras y examen final. Todo queda grabado para retomarlo.": "掌握你語料庫中的一個主題：全景、帶原文引用的站點、對比、邊界和期末測驗。一切都會被儲存，以便隨時繼續。",
  "Domina un tema de tu corpus: el contenido y el progreso se guardan para retomarlos; tus respuestas se borran al reiniciar.": "掌握你語料庫中的一個主題：內容和進度會被儲存以便繼續；你的答案會在重新開始時清除。",
  "Buscar entre tus inmersiones…": "搜尋你的沉浸…",
  "Cargando inmersiones…": "正在載入沉浸…",
  "Ninguna inmersión coincide con tu búsqueda.": "沒有沉浸與你的搜尋匹配。",
  "Aún no hay inmersiones. Crea la primera y quedará aquí, con su progreso y tus respuestas, lista para retomarla.": "還沒有沉浸。建立第一個，它會連同進度和你的答案保留在這裡，隨時可以繼續。",
  "Aún no hay inmersiones. Crea la primera y quedará aquí, con su progreso, lista para retomarla.": "還沒有沉浸。建立第一個，它會連同進度保留在這裡，隨時可以繼續。",
  "Reiniciar borra las respuestas anteriores y comienza el recorrido desde el principio.": "重新開始會清除之前的答案，並從頭開始整個流程。",
  "Elige el tema y el alcance. Antes de generar verás qué sabe tu corpus (sin IA).": "選擇主題和範圍。生成之前，你會看到你的語料庫瞭解什麼（暫不使用 AI）。",
  "Novedades": "新功能",
  "Esto es lo nuevo en esta versión de Nodus.": "這是此版本 Nodus 中的新內容。",
  "¡Entendido!": "知道了！",
  "Plegar": "摺疊",
  "Desplegar": "展開",
  "Elige las colecciones a monitorizar. Despliega cualquier colección para elegir subcolecciones concretas si una es demasiado grande. Se incorporan metadatos; los análisis se lanzan manualmente salvo que actives automatización en Ajustes.": "選擇要監控的集合。如果某個集合太大，可展開它以選擇具體的子集合。後設資料會被匯入；除非在設定中啟用自動化，否則分析將手動執行。",
  "Fuentes primarias": "原始資料",
  "Genealogía": "家譜",
  "próximamente": "即將推出",
  "Tipo de bóveda: {type}.": "知識庫型別：{type}。",
  "Mi bóveda": "我的知識庫",
  "TU PRIMERA BÓVEDA": "你的第一個知識庫",
  "Vamos a crear tu primera bóveda": "我們來建立你的第一個知識庫",
  "Ponle un nombre y elige su modo. El modo decide qué secciones verás y cómo trabaja la IA contigo; puedes crear más bóvedas, de otros modos, cuando quieras.": "為它命名並選擇模式。模式決定你會看到哪些板塊以及 AI 如何與你協作；你可以隨時建立更多其他模式的知識庫。",
  "Después el asistente te ayudará a elegir su modelo de IA y su modelo de embeddings. Puedes cambiar el nombre en cualquier momento desde el selector de bóvedas.": "隨後嚮導會幫助你選擇其 AI 模型和嵌入模型。你可以隨時從知識庫切換器中重新命名。",
  "Crear mi bóveda": "建立我的知識庫",
