  "Parentescos sugeridos": "建議的親屬關係",
  "Aún no hay personas. Se crean al analizar fuentes primarias o añadiéndolas a mano.": "還沒有人物。它們會在分析原始資料或手動新增時建立。",
  "sin fechas": "無日期",
  "Selecciona una persona para ver su ficha, sus eventos y la evidencia que la respalda.": "選擇一個人物以檢視其檔案、事件以及支援證據。",
  "Propuestos a partir de la evidencia de las fuentes. Tú confirmas; nada se añade al árbol solo.": "根據資料中的證據推斷。由你確認；不會自動向家譜中新增任何內容。",
