  "Seis obras sobre la ciencia del aprendizaje con grafo, notas, mapa de investigación, inmersión, borradores, informe profundo y proyecto guardado; sin conectar Zotero ni configurar IA.": "六篇關於學習科學的文獻，包含圖譜、筆記、研究地圖、沉浸、草稿、深度報告和已儲存的專案；無需連線 Zotero 或配置 AI。",
  "Cargar demo académica": "載入學術演示",
