  "Una familia del siglo XIX con árbol, cronología, mapa, archivo, biblioteca, notas, relaciones y un informe de investigación guardado. Incluye un tutorial guiado.": "一個十九世紀家族，包含族譜、時間線、地圖、檔案、文獻庫、筆記、關係以及一份已儲存的研究報告。包含引導教程。",
