  "Importa un árbol GEDCOM (desde Gramps, Ancestry…) en Personas, o sube tus documentos —partidas, censos, cartas— al Archivo y extrae de ellos personas y eventos.": "在「人物」中匯入 GEDCOM 家譜（來自 Gramps、Ancestry…），或將你的文件——記錄、人口普查、書信——上傳到「檔案」，並從中提取人物和事件。",
