  "Usar esta voz": "使用此語音",
  "Descárgala para poder usarla": "下載後才能使用",
  "en uso": "使用中",
  "descarga el modelo": "下載模型",
  "Lugares": "地點",
  "Añadir lugar": "新增地點",
  "Nuevo lugar": "新地點",
  "Busca un lugar y registra su relación con esta persona.": "搜尋一個地點並記錄其與這個人的關係。",
  "Registra los lugares de esta persona (municipio, estado, país). Construyen su mapa individual y alimentan el mapa general.": "記錄這個人的地點（市、州、國家）。它們構成其個人地圖，併為總地圖提供資料。",
  "Sin lugares registrados.": "未記錄任何地點。",
  "sin coordenadas": "無座標",
  "Guardar lugar": "儲存地點",
  "Eliminar lugar": "刪除地點",
  "¿Eliminar «{name}» de los lugares de esta persona?": "要從這個人的地點中刪除「{name}」嗎？",
  "Eliminar persona": "刪除人物",
  "Eliminar evento": "刪除事件",
  "Buscar un lugar (municipio, ciudad…)": "搜尋地點（市、城市…）",
  "Sin coincidencias. Prueba con el nombre en su idioma original.": "沒有匹配項。請嘗試使用其原始語言的名稱。",
  "+{n} más": "+{n} 個",
  "Ningún lugar localizado todavía. Añade lugares a las personas (con su municipio, estado y país) para verlos en el mapa.": "尚未定位任何地點。為人物新增地點（包含市、州和國家），即可在地圖上看到它們。",
  "Ningún lugar localizado todavía. Abre la ficha de una persona y añade sus lugares (municipio, estado, país); aparecerán aquí sobre el mapa.": "尚未定位任何地點。開啟某個人物的檔案並新增其地點（市、州、國家）；它們將顯示在此處的地圖上。",
  "Reproducir la línea temporal": "播放時間線",
