  "Si el equipo estaba apagado, la copia se hace al arrancar la app.": "如果電腦處於關機狀態，備份將在應用啟動時進行。",
  "Base de datos nueva": "新建資料庫",
  "Nueva base de datos": "新資料庫",
  "Aún no hay bases de datos.": "還沒有資料庫。",
  "Chat de datos": "資料對話",
  "Eliminar fila": "刪除行",
  "¿Eliminar esta fila?": "要刪除此行嗎？",
  "Eliminar base de datos": "刪除資料庫",
  "¿Eliminar la base de datos «{name}»? Se borrarán todas sus filas y columnas.": "要刪除資料庫「{name}」嗎？其所有行和列都將被刪除。",
  "Selecciona o crea una base de datos": "選擇或建立一個數據庫",
  "Las bases de datos aparecen en la barra lateral. Crea la primera para empezar.": "資料庫會顯示在側邊欄中。建立第一個即可開始。",
  "entradas": "條目",
  "Nueva fila": "新建行",
  "Añade una columna para empezar.": "新增一列即可開始。",
  "Sin filas todavía. Añade la primera.": "還沒有行。新增第一行吧。",
  "Nombre de la columna": "列名",
  "Eliminar columna": "刪除列",
  "¿Eliminar la columna «{name}»?": "要刪除列「{name}」嗎？",
  "Cambiar tipo": "更改型別",
  "Opciones": "選項",
  "Añadir opción": "新增選項",
  "Añadir columna": "新增列",
  "El análisis estadístico y los informes con IA sobre tus bases de datos llegarán en una próxima fase.": "對資料庫的統計分析和 AI 報告將在後續階段推出。",
  "El chat de datos, con gráficos y consultas reproducibles sobre tus bases de datos, llegará en una próxima fase.": "資料對話——支援圖表和可復現查詢你的資料庫——將在後續階段推出。",
  "Tus datos estructurados: tablas con columnas tipadas, análisis y chat.": "你的結構化資料：帶有型別化列的表格、分析和對話。",
  "Crear la primera": "建立第一個",
  "{n} entradas": "{n} 個條目",
  "Estadísticas e informes con IA sobre una base de datos.": "對資料庫的統計與 AI 報告。",
  "Pregunta a tus datos ({n} entradas en total).": "向你的資料提問（共 {n} 個條目）。",
  "Número": "數字",
  "Selección múltiple": "多選",
  "Casilla": "核取方塊",
