  "Resume el contenido de esta fila en una o dos frases claras.": "用一兩句清晰的話概括此行內容。",
  "Clasifica esta fila en una categoría breve (una o dos palabras). Devuelve solo la categoría.": "將此行歸入一個簡短的類別（一兩個詞）。只返回類別。",
  "Extrae de 3 a 5 palabras clave separadas por comas. Devuelve solo las palabras clave.": "提取 3 到 5 個用逗號分隔的關鍵詞。只返回關鍵詞。",
  "Indica el sentimiento del contenido: positivo, negativo o neutro. Devuelve solo una palabra.": "判斷內容的情感傾向：正面、負面或中性。只返回一個詞。",
  "Traduce el contenido principal de esta fila al inglés. Devuelve solo la traducción.": "將此行的主要內容翻譯為英語。只返回譯文。",
  "Describe en 40-60 palabras la imagen adjunta a esta fila.": "用 40-60 個詞描述此行附帶的圖片。",
  "Transcribe literalmente todo el texto que aparezca en la imagen o archivo adjunto. Devuelve solo la transcripción.": "逐字轉寫圖片或附件中出現的所有文本。只返回轉寫內容。",
