  "Actualizar vista": "更新檢視",
  "Demo de bases de datos": "資料庫演示",
  "Tres tablas de investigación con todos los tipos de columna, relaciones, registros, análisis, una conversación y notas de ejemplo. Incluye un tutorial guiado.": "三張研究表，涵蓋所有列型別、關係、記錄、分析、一段對話和示例筆記。包含引導式教程。",
  "Cargar demo de bases de datos": "載入資料庫演示",
  "Cargar datos de ejemplo": "載入示例資料",
  "Tutorial de bases de datos": "資料庫教程",
  "La lista de bases de datos, la tabla con columnas tipadas, la edición de celdas y las secciones de análisis y chat.": "資料庫列表、帶型別的列表格、單元格編輯，以及分析和聊天部分。",
  "Se mostrará el tutorial de bases de datos.": "將顯示資料庫教程。",
  "Bienvenido al modo bases de datos": "歡迎使用資料庫模式",
  "Este es el modo bases de datos de Nodus: un gestor de tablas al estilo Notion, integrado en tu app. Te enseño en un minuto sus piezas con tres bases de datos de ejemplo ya cargadas. Puedes salir cuando quieras y volver a ver el tutorial desde Ajustes.": "這是 Nodus 的資料庫模式：一個內置於應用中的 Notion 風格表格管理器。我將用一分鐘通過三個已載入的示例資料庫帶你瞭解它的各個部分。你可以隨時退出，並從設定中重新觀看教程。",
  "Tus bases de datos": "你的資料庫",
  "En la barra lateral aparecen todas tus bases de datos. Cada una tiene un identificador único autogenerado. Pulsa una para abrirla, o el botón + para crear una nueva. Aquí abajo están también las secciones de Análisis y Chat.": "所有資料庫都會顯示在側邊欄中。每個資料庫都有一個自動生成的唯一識別符號。點選即可開啟，或點選 + 按鈕新建一個。下方還有分析和聊天部分。",
  "La tabla": "表格",
  "Cada base de datos es una tabla de columnas tipadas: título, texto, número, fecha, hora, selección, selección múltiple y casilla. Arriba verás el número total de entradas y el porcentaje que suponen del total de todas tus bases de datos.": "每個資料庫都是一張包含各類列的表格：標題、文本、數字、日期、時間、單選、多選和核取方塊。頂部會顯示條目總數，以及它們佔你所有資料庫總數的百分比。",
  "Edita directamente": "就地編輯",
  "Haz clic en cualquier celda para editarla al momento. Las columnas de selección muestran opciones con color que puedes añadir sobre la marcha; las casillas se marcan con un clic. Pasa el ratón por una fila para borrarla.": "點選任意單元格即可立即編輯。單選列會顯示帶顏色的選項，你可以隨時新增；核取方塊點選即可切換。將滑鼠懸停在某行上可將其刪除。",
  "Columnas a tu medida": "按需定製列",
  "Pulsa la cabecera de una columna para renombrarla, cambiar su tipo o gestionar sus opciones, y usa el botón + del final de la cabecera para añadir nuevas columnas. Con «Nueva fila» añades registros.": "點選列標題可重新命名、更改型別或管理其選項，並使用標題末尾的 + 按鈕新增新列。通過「新建行」新增記錄。",
  "Análisis (próximamente)": "分析（即將推出）",
  "Aquí podrás elegir una base de datos y obtener estadísticas automáticas más un informe con IA, con gráficos y el cálculo a la vista para que sea reproducible. Llega en una próxima fase.": "在這裡，你可以選擇一個數據庫，獲取自動統計資料和 AI 報告，附帶圖表和可見的計算過程，以確保可復現。將在後續階段推出。",
  "Chat de datos (próximamente)": "資料聊天（即將推出）",
  "Un chat adaptado para conversar con una o varias de tus bases de datos, capaz de generar gráficos y consultas reproducibles. También llega en una próxima fase.": "專為與你的一個或多個數據庫對話而設計的聊天功能，能夠生成圖表和可復現的查詢。同樣將在後續階段推出。",
  "Listo para tus datos": "為你的資料做好準備",
  "Esto es una demostración con datos de ejemplo. Cuando quieras empezar con los tuyos, crea una base de datos desde la barra lateral y añade tus columnas. Pronto podrás además importar CSV y subir archivos en masa.": "這是一個使用示例資料的演示。當你想開始使用自己的資料時，從側邊欄建立一個數據庫並新增列。很快你還可以匯入 CSV 並批次上傳檔案。",
