  "Nodus puede extraer conceptos, relaciones y citas textuales para crear el mapa de Ideas y el grafo de estudio.": "Nodus 可以提取概念、關係和原文引文，用於建立觀點圖譜和學習圖譜。",
  "El análisis se realizará en este dispositivo con el modelo seleccionado; el archivo no saldrá del equipo.": "分析將使用所選模型在本裝置上進行；檔案不會離開本機。",
  "Se enviarán al proveedor indicado el título y el texto extraído necesario. El archivo original permanecerá en tu dispositivo.": "會將標題和必要的提取文本傳送給指定的提供商。原始檔案將保留在你的裝置上。",
