  "Controla si Nodus crea automáticamente conceptos, citas y relaciones para el mapa de Ideas y el grafo de estudio.": "控制 Nodus 是否自動為觀點圖譜和學習圖譜建立概念、引文和關係。",
  "Preguntar cada vez": "每次詢問",
