  "Usar modelo de estudio/síntesis": "使用學習/綜合模型",
  "Sin modelo alternativo": "無備用模型",
  "Modelo del proveedor": "提供商模型",
  "Heredar modelo principal": "繼承主要模型",
  "Lleva tus notas, datos de estudio, materiales y grabaciones, borradores, búsquedas guardadas, auditorías de relaciones, bases de datos y Copias protegidas a otro equipo. Al importar se fusiona por fecha: gana la versión más reciente; las eliminaciones de Copias protegidas también se sincronizan mediante borrado lógico.": "將你的筆記、學習資料、材料和錄音、草稿、已儲存的搜尋、關係審計、資料庫和保護副本帶到另一臺電腦。匯入時按日期合併：以最新版本為準；保護副本的刪除也通過軟刪除進行同步。",
  "Esta acción elimina datos de forma permanente. ¿Quieres continuar?": "此操作會永久刪除資料。是否繼續？",
