  "Paquete": "打包",
  "Analíticas de estudio desactivadas": "學習分析已停用",
  "Puedes activarlas en Ajustes → Modelos IA. Los repasos siguen funcionando localmente.": "你可以在設定 → AI 模型中啟用它們。複習仍可在本地進行。",
  "Modelos de IA": "AI 模型",
  "Un modelo general atiende conversación, análisis, resúmenes y las demás tareas de texto. Las capacidades especializadas se configuran debajo.": "一個通用模型負責對話、分析、摘要及其他文本任務。專業能力在下方配置。",
  "El modelo general sigue siendo la base. Cada selector vacío hereda de él; los modelos de las herramientas se guardan solo en el vault actual.": "通用模型仍是基礎。每個空白選擇器都會繼承它；工具的模型僅儲存在當前知識庫中。",
  "Cada tarea utiliza el modelo concreto seleccionado. Los modelos de las herramientas se guardan solo en el vault actual.": "每項任務使用所選的特定模型。工具的模型僅儲存在當前知識庫中。",
  "Modelo general de texto": "通用文本模型",
  "Conversación, análisis, resúmenes y fallback de cualquier tarea sin modelo propio.": "對話、分析、摘要，以及任何沒有專屬模型的任務的備用模型。",
  "Conversación, análisis, resúmenes y demás tareas de texto.": "對話、分析、摘要及其他文本任務。",
  "Este modelo consume la cuota de tu suscripción, no crédito de API. Un análisis completo del corpus puede agotar el límite semanal o mensual de tu plan.": "此模型消耗你的訂閱配額，而非 API 額度。對語料庫進行完整分析可能會用盡你套餐的每週或每月限額。",
  "Este modelo local es de visión y no extrae ideas de forma fiable (tiende a divagar y no cerrar el JSON). Para extracción, elige Gemma 4 E2B u otro modelo mayor.": "此本地模型面向視覺，無法可靠地提取觀點（容易偏離主題且不會閉合 JSON）。如需提取，請選擇 Gemma 4 E2B 或更大型的模型。",
  "Estos pesos son los mismos que Nodus descarta entre sus modelos integrados: al extraer ideas divagan y no cierran el JSON. Puedes usarlos igualmente, pero para extracción conviene un modelo mayor.": "這些權重與 Nodus 在內建模型中排除的相同：提取觀點時會偏離主題且不閉合 JSON。你仍可以使用它們，但提取更適合使用更大型的模型。",
  "El paso falló sin dejar un motivo. Reintenta; si vuelve a fallar, revisa el modelo en Ajustes → Modelos de IA.": "該步驟失敗且未記錄原因。請重試；如果再次失敗，請在設定 → AI 模型中檢查模型。",
  "Todavía no hay ningún modelo entre los que elegir. Pulsa «Cargar modelos» para ver los de tus proveedores, o marca los que quieras como favoritos en Ajustes → Proveedores de IA y modelos.": "目前沒有可供選擇的模型。點選「載入模型」檢視你的提供商提供的模型，或在設定 → AI 提供商和模型中將要用的標記為收藏。",
  "Sin respuesta de {list}. Revisa su clave o que el servidor local esté abierto.": "{list} 無響應。請檢查其金鑰，或確認本地伺服器已啟動。",
  "solo visión": "僅視覺",
  "Este modelo no puede usarse para extracción de ideas.": "此模型不能用於提取觀點。",
  "Uso mi plan gratuito de este proveedor": "我使用此提供商的免費套餐",
  "Ajusta las peticiones a los límites del nivel gratuito (recorta la longitud de salida y espera si se alcanza el límite por minuto) para que el análisis no falle. Déjalo desmarcado si pagas por uso.": "將請求調整到免費層級的限制內（縮短輸出長度，並在達到每分鐘限額時等待），以免分析失敗。如果你按用量付費，請保持未勾選。",
