  "Se eliminará «{model}» del almacenamiento de Nodus. Si está seleccionado, las funciones que lo usan dejarán de funcionar hasta que elijas otro modelo o vuelvas a descargarlo.": "將從Nodus儲存中刪除「{model}」。如果它已被選中，使用它的功能將停止工作，直到你選擇其他模型或重新下載它。",
  "Cambiar modelo de embeddings": "更改嵌入模型",
  "Los embeddings creados con el modelo anterior no son compatibles con el nuevo. Nodus conservará los datos, pero tendrás que reindexar para que la búsqueda semántica y las relaciones usen el nuevo modelo. ¿Cambiar de todos modos?": "使用舊模型建立的嵌入與新模型不相容。Nodus會保留資料，但你必須重新建立索引，語義搜尋和關係才能使用新模型。仍要更改嗎？",
  "Cambiar modelo": "更改模型",
  "Si cambias de modelo de embeddings, los vectores anteriores no servirán con el nuevo modelo y tendrás que reindexar.": "如果更換嵌入模型，原有向量將無法與新模型配合使用，你必須重新建立索引。",
  "Embeddings multilingües de alta calidad para corpus amplios.": "面向大型語料庫的高質量多語言嵌入。",
  "Embeddings multilingües con contexto largo y buen equilibrio entre precisión y memoria.": "長上下文多語言嵌入，在精度與記憶體佔用之間取得良好平衡。",
  "Opción ligera y rápida para equipos con menos memoria.": "適合記憶體較少電腦的輕量快速選項。",
  "Modelo visual muy ligero para conversación, resúmenes e ideas.": "非常輕量的視覺模型，適用於對話、摘要和觀點。",
  "Modelo visual de mayor calidad; requiere más almacenamiento y memoria.": "質量更高的視覺模型；需要更多儲存空間和記憶體。",
  "Modelo visual compacto orientado a documentos e imágenes.": "面向文件和影像的緊湊視覺模型。",
  "Guía esencial de Nodus e IA": "Nodus與AI基礎指南",
  "Bóvedas, modelos locales, API keys, costes, embeddings y voz explicados desde cero.": "從零講解知識庫、本地模型、API金鑰、費用、嵌入和語音。",
  "Se mostrará la guía esencial.": "將顯示基礎指南。",
