  "Si el archivo permite extraer texto automáticamente, Nodus lo hará al guardarlo. Este campo permite añadirlo o sustituirlo manualmente.": "如果檔案可以自動提取文本，Nodus 將在儲存時完成提取。此欄位可讓你手動新增或替換文本。",
  "Guardar entrada": "儲存記錄",
  "Ideas de estudio": "學習觀點",
  "Grafo de estudio": "學習圖譜",
  "Buscando actualizaciones…": "正在檢查更新…",
  "Actualización {version} encontrada. La descarga empezará automáticamente.": "發現更新 {version}。將自動開始下載。",
  "Descargando actualización… {percent}%": "正在下載更新… {percent}%",
  "Actualización {version} descargada. Reiniciando para instalarla…": "更新 {version} 已下載。正在重啟以安裝…",
  "Instalando Nodus {version} y reiniciando…": "正在安裝 Nodus {version} 並重啟…",
