  "Demasiado fácil": "太簡單",
  "Demasiado difícil": "太難",
  "Aprobar y bloquear": "批准並鎖定",
  "Crea primero un curso.": "請先建立課程。",
  "Crea primero un curso y una asignatura.": "請先建立課程和科目。",
  "Escribe un nombre": "輸入名稱",
  "Híbrida": "混合",
  "Verificar": "驗證",
  "Verificar de nuevo": "重新驗證",
  "Cambios sin guardar": "未儲存的更改",
  "Error al guardar": "儲存錯誤",
  "Chat con el corpus": "與語料庫對話",
  "Mejora de texto": "文本最佳化",
  "Detalles y fuente": "詳情與來源",
  "Verificar ideas extraídas": "驗證提取的觀點",
  "Cada idea aparece con su tipo (afirmación, hallazgo, constructo, método o marco), la obra de la que procede y la cita textual que la sostiene. Abre el detalle para comprobar si la lectura automática coincide con la tuya.": "每個觀點都會顯示其型別（主張、發現、構念、方法或框架）、所屬文獻及支撐它的原文引用。開啟詳情可核對自動解讀是否與你的判斷一致。",
  "Busca por palabras clave a través de ideas, obras, huecos, temas, autores y notas. Los resultados te llevan directamente al detalle correspondiente en cada vista.": "按關鍵詞搜尋觀點、文獻、空白、主題、作者和筆記。結果會直接帶你進入各檢視中對應的詳情。",
  "Tu espacio de notas": "你的筆記空間",
  "Crea carpetas y notas en Markdown. Captura respuestas del asistente, borradores del taller de escritura, síntesis de debates e ideas individuales. Las citas internas (nodus://) permanecen clicables.": "建立資料夾和 Markdown 筆記。記錄助手回答、寫作工作坊草稿、辯論綜述和單個觀點。內部引用（nodus://）保持可點選。",
  "Debates: la estructura de una contradicción": "辯論：矛盾的結構",
  "Cada relación de contradicción o refutación se despliega como un debate de dos bandos con sus autores, evidencias y cronología. Pides una síntesis al modelo para entender la tensión y decides cómo tu trabajo puede resolverla o aprovecharla.": "每條矛盾或反駁關係都會展開為一場兩方辯論，包含雙方作者、證據和時間線。你向模型請求綜述以理解這種張力，再決定你的工作如何化解或利用它。",
  "Mapa de cobertura: tu pregunta descompuesta": "覆蓋圖：拆解你的問題",
  "Escribe tu pregunta de investigación y Nodus la desglosa en subpreguntas. Después mapea cuáles cubre tu corpus, cuáles parcialmente y cuáles quedan sin literatura. Es la herramienta para convertir una intuición vaga en un plan de búsqueda estructurado.": "輸入你的研究問題，Nodus 會將其拆解為子問題。隨後它會標出你的語料庫覆蓋了哪些、部分覆蓋了哪些、哪些尚無文獻。這是把模糊直覺轉化為結構化檢索計劃的工具。",
  "Notas: tu cuaderno de investigación": "筆記：你的研究筆記本",
  "A lo largo del proceso habrás generado hallazgos en el asistente, borradores en el taller y síntesis de debates. Las Notas te permiten organizar todo ello en carpetas jerárquicas — piensa en capítulos y secciones — con un editor Markdown que conserva las citas clicables. Las ideas manuales que crees aquí se integran directamente en el grafo.": "在研究過程中，你會在助手中生成發現、在工作坊中生成草稿、在辯論中生成綜述。筆記讓你把這一切整理到層級資料夾中——可以理解為章節和小節——並配有保持引用可點選的 Markdown 編輯器。你在此建立的手動觀點會直接進入圖譜。",
  "Inicio resume el estado de tu corpus, los análisis pendientes y el siguiente paso recomendado. La investigación es iterativa: escaneas más obras, vuelven a aparecer ideas y huecos, refinas la ruta y el borrador. Vuelve aquí entre vueltas. Puedes relanzar este recorrido desde Ajustes → Ayuda.": "首頁彙總你的語料庫狀態、待處理的分析和推薦的下一步。研究是迭代的：你掃描更多文獻，觀點和空白會再次出現，你不斷最佳化路線和草稿。每一輪之間回到這裡。你可以從 設定 → 幫助 重新啟動此導覽。",
  "RECUPERACIÓN ACTIVADA": "恢復已啟用",
  "Tus datos ya están protegidos": "你的資料現已受到保護",
  "Tus datos se han recuperado": "你的資料已恢復",
  "bóveda(s)": "知識庫",
  "Clave de recuperación independiente": "獨立恢復金鑰",
  "Permite recuperar tus copias aunque olvides la contraseña.": "即使忘記密碼，也能恢復你的備份。",
  "Guarda el kit fuera de este dispositivo. Podrás restaurar con la contraseña o con la clave de recuperación.": "請將恢復套件儲存在此裝置之外。你可以使用密碼或恢復金鑰進行恢復。",
  "Continuar a Nodus": "繼續進入 Nodus",
  "PROTECCIÓN DE DATOS": "資料保護",
  "Hemos detectado una instalación anterior": "我們檢測到已有的安裝",
  "Elige dónde proteger Nodus": "選擇 Nodus 的保護位置",
  "Tus bóvedas actuales no se moverán ni se modificarán. Crearemos una primera copia cifrada y verificada antes de activar la recuperación.": "你當前的知識庫不會被移動或修改。我們會在啟用恢復前建立一個經過驗證的加密備份。",
  "Configura una carpeta segura antes de empezar. Tus bóvedas seguirán trabajando localmente y Nodus guardará aquí copias recuperables.": "開始前請配置一個安全資料夾。你的知識庫仍將在本地工作，Nodus 會在此儲存可恢復的備份。",
  "La base de datos activa nunca se abre directamente desde Google Drive o Dropbox: así evitamos conflictos y corrupción.": "活動資料庫絕不會直接從 Google Drive 或 Dropbox 開啟：這樣可避免衝突和損壞。",
  "Migrar y proteger este equipo": "遷移並保護此電腦",
  "Crear carpeta segura": "建立安全資料夾",
  "Recuperar otro equipo": "恢復其他電腦",
  "1. Selecciona una carpeta vacía": "1. 選擇一個空資料夾",
  "1. Selecciona la carpeta existente": "1. 選擇現有資料夾",
  "Puede ser una carpeta local o una carpeta sincronizada por Google Drive, Dropbox, iCloud u otro servicio. Debe estar vacía.": "可以是本地資料夾，也可以是由 Google Drive、Dropbox、iCloud 或其他服務同步的資料夾。必須為空。",
  "Busca la carpeta que contiene nodus-recovery.json y sus copias.": "選擇包含 nodus-recovery.json 及其備份的資料夾。",
  "2. Todo Nodus quedará protegido": "2. 整個 Nodus 都將受到保護",
  "Sin selecciones ni exclusiones: todas las bóvedas, documentos, preferencias, historiales, medios y claves API se incluirán automáticamente.": "無需選擇或排除：所有知識庫、文件、偏好設定、歷史記錄、媒體檔案和 API 金鑰都會自動納入。",
  "2. Elige una copia": "2. 選擇一份備份",
  "La más reciente aparece seleccionada. Puedes recuperar una versión anterior.": "預設選中最新的一份。你也可以恢復較舊的版本。",
  "3. Crea una contraseña maestra": "3. 建立主密碼",
  "3. Introduce una credencial": "3. 輸入憑據",
  "Protege tus copias junto con una clave de recuperación independiente. Debe tener al menos 8 caracteres.": "為你的備份配置獨立恢復金鑰。密碼至少需要 8 個字元。",
  "Puedes usar la contraseña maestra o la clave de recuperación de tu kit.": "你可以使用主密碼或恢復套件中的恢復金鑰。",
  "Contraseña o clave de recuperación": "密碼或恢復金鑰",
  "Contraseña maestra": "主密碼",
  "Repite la contraseña": "重複密碼",
  "Las contraseñas no coinciden.": "兩次輸入的密碼不一致。",
  "La contraseña cumple el mínimo de 8 caracteres.": "密碼滿足至少 8 個字元的要求。",
  "La contraseña debe tener al menos 8 caracteres. Los números y símbolos son opcionales.": "密碼至少需要 8 個字元。數字和符號為可選項。",
  "Repite la contraseña para confirmar.": "請重複密碼以確認。",
  "AES-256-GCM · instantáneas SQLite consistentes · hashes de integridad": "AES-256-GCM · 一致的 SQLite 快照 · 完整性雜湊",
  "Verificando y guardando…": "正在驗證並儲存…",
