  "Verificar y recuperar": "驗證並恢復",
  "¿Saltar la guía esencial?": "跳過基礎指南？",
  "Esta guía explica los espacios de trabajo, los modelos que funcionan en tu equipo, los servicios externos y las búsquedas por significado.": "本指南介紹工作區、可在你電腦上執行的模型、外部服務以及按語義搜尋。",
  "Continuar tutorial": "繼續教程",
  "Saltar de todos modos": "仍然跳過",
  "Al adjuntar, además de guardar el archivo:": "附加時，除儲存檔案外：",
  "Columna vacía con nombre de archivo: lista para adjuntar": "帶有檔名樣式的空列：可附加檔案",
  "Con {n} archivos esto puede tardar horas. Puedes adjuntarlos ahora y hacerlo después por columnas.": "有 {n} 個檔案時，這可能需要數小時。你可以現在附加，之後再按列處理。",
  "Código en el nombre (opcional)": "檔名中的程式碼（可選）",
  "Describir cada imagen con IA": "用 AI 描述每張圖片",
  "Déjalo vacío para detectar el código automáticamente.": "留空可自動檢測程式碼。",
  "Ej.: @@###-@@### · # dígito, @ letra, * cualquier cosa": "例如：@@###-@@### · # 數字，@ 字母，* 任意字元",
  "Ej.: {v}": "例如：{v}",
  "Elige archivos o una carpeta completa. Nodus empareja cada archivo con su fila por el nombre exacto y, si no, por el código del catálogo que compartan (LV001-FG001).": "選擇檔案或整個資料夾。Nodus 會按完全相同的名稱將每個檔案與其行配對；若無法匹配，則按它們共有的目錄程式碼（LV001-FG001）配對。",
  "Emparejar también por parecido del nombre (menos preciso)": "也按名稱相似度配對（精度較低）",
  "Ese patrón no es válido.": "該模式無效。",
  "Extraer el texto (OCR)": "提取文本（OCR）",
  "Hay más de una columna de título. Solo la primera identificará la fila.": "有多個標題列。只有第一列會用於標識行。",
