  "{n} columnas · {r} filas. Nodus ha sugerido un tipo para cada una; cámbialo o descarta las que no necesites.": "{n} 列 · {r} 行。Nodus 已為每列建議了型別；你可以更改，或丟棄不需要的列。",
  "{n} vacíos": "{n} 個空值",
  "Hay demasiados archivos sin pareja para compararlos por parecido. Revisa la columna de referencia o el código.": "未配對的檔案太多，無法按相似度比較。請檢查參考列或程式碼。",
