  "El hilo es público: describe los casos en abstracto, sin datos reales de alumnado.": "該帖子是公開的：請抽象描述案例，不要包含真實的學生資料。",
  "Qué esperarías poder hacer en esta sección": "你希望在這一節能做什麼",
