  "Word, Excel, la plataforma del centro, papel… y qué te hace perder más tiempo.": "Word、Excel、學校平臺、紙質材料…以及什麼最耗費你的時間。",
  "Qué no debería hacer (opcional)": "不應該做什麼（可選）",
  "Automatismos que te molestarían o decisiones que prefieres tomar tú.": "會讓你覺得煩擾的自動化，或你更願意自己做的決定。",
