  "Descendencia": "後代",
  "Notas libres sobre este personaje, en Markdown…": "關於此角色的自由筆記，Markdown格式…",
  "Lo que se ve. Es lo único que alimenta la generación de imágenes.": "可見的外貌。它是影像生成的唯一依據。",
  "Rasgos, complexión, ropa, marcas distintivas…": "五官、體型、衣著、顯著特徵…",
  "Personalidad": "性格",
  "Cómo es y cómo habla.": "其為人與說話方式。",
  "Carácter, motivaciones, miedos, forma de hablar…": "性格、動機、恐懼、說話方式…",
  "Trasfondo": "背景",
  "De dónde viene y qué le ha pasado.": "其來歷與過往經歷。",
  "Origen, historia previa, cómo llega al punto en que empieza el relato…": "出身、過往經歷、如何走到故事開始之處…",
  "Semilla visual": "視覺種子",
  "Un texto corto y estable que se añade a TODAS las imágenes que generes de este personaje. Es lo que consigue que se parezca a sí mismo de una imagen a otra, así que conviene cambiarlo lo menos posible.": "一段簡短而固定的文本，會新增到該角色生成的每一張影像中。它能讓角色在不同影像中保持一致的外貌，因此應儘量少修改。",
  "p. ej. «semielfo de rasgos afilados, pelo negro recogido, ojos ámbar»": "例如«五官銳利的半精靈，黑髮束起，琥珀色眼睛»",
  "Usar la apariencia como semilla": "將外貌用作種子",
  "Redacta una biografía narrativa a partir de la ficha: su descripción, sus eventos y sus vínculos.": "根據檔案撰寫敘事傳記：其描述、經歷的事件與羈絆。",
  "Rellena al menos la descripción, un evento o un vínculo antes de generar la biografía.": "生成傳記前，請至少填寫描述、一個事件或一條羈絆。",
  "Generada con IA": "AI生成",
