  "p. ej. 1204 (admite negativos)": "例如 1204（可為負數）",
  "La fecha se escribe como quieras; el año del mundo es lo que ordena la lista.": "日期可隨意書寫；列表按世界年份排序。",
  "{n} sin año del mundo: aparecen al final hasta que les pongas uno.": "{n} 條無世界年份：在設定之前會一直排在末尾。",
  "Nacimiento (texto libre)": "出生（自由文本）",
  "Muerte (texto libre)": "死亡（自由文本）",
