  "Año del mundo · muerte": "世界年份 · 死亡",
  "La fecha se muestra tal como la escribas. El año del mundo es un entero y sirve solo para ordenar.": "日期按你所寫顯示。世界年份為整數，僅用於排序。",
  "Subir imagen": "上傳影像",
  "Arrastra para encuadrar": "拖動以調整構圖",
  "Arrastra la imagen para encuadrarla y usa el zoom.": "拖動影像調整構圖，並使用縮放。",
  "Retrato con IA": "AI肖像",
  "Se usa la apariencia y la semilla visual de la ficha, así que el personaje mantiene el mismo aspecto entre imágenes.": "使用檔案中的外貌與視覺種子，因此角色在影像之間保持一致的外貌。",
  "Escribe primero la apariencia del personaje en la sección Descripción.": "請先在描述部分填寫角色的外貌。",
  "Solo para esta imagen: pose, gesto, ropa, luz… (opcional)": "僅用於此影像：姿勢、動作、衣著、光線…（可選）",
  "Tu mundo": "你的世界",
  "Construye un mundo de ficción pieza a pieza. Empieza por los personajes: sus nombres y alias, los hechos de su vida, sus vínculos y su descripción, con retratos y biografías que puedes generar cuando te sirvan.": "一點一滴構建你的虛構世界。從角色開始：他們的姓名與化名、生平事件、羈絆與描述，還可以在需要時生成肖像和傳記。",
  "Personajes recientes": "最近的角色",
  "Ver todos": "檢視全部",
  "En construcción": "建設中",
  "Las demás secciones del menú ({sections}) aparecen atenuadas porque todavía no están construidas. Se irán activando una a una.": "選單中的其他部分（{sections}）因尚未構建而顯示為灰色。它們將陸續啟用。",
  "enciclopedia, lugares, facciones, culturas, cronología, mapa, relaciones, escenas y manuscritos": "百科全書、地點、派系、文化、年表、地圖、關係、場景和手稿",
