  "Muere el año {death}, antes de nacer el año {birth}.": "死於 {death} 年，早於 {birth} 年出生。",
  "Participa en un hecho el año {year}, después de morir el año {death}.": "參與 {year} 年的事件，晚於 {death} 年死亡。",
  "Participa en un hecho el año {year}, antes de nacer el año {birth}.": "參與 {year} 年的事件，早於 {birth} 年出生。",
  "Tiene fecha de muerte pero su estado sigue siendo «vivo».": "有死亡日期，但狀態仍為«在世»。",
  "Está marcado como muerto pero no consta cuándo.": "標記為已故，但未記錄死亡時間。",
  "El nombre se parece mucho a «{other}»: quien lea puede confundirlos.": "名稱與«{other}»很相似：讀者可能會混淆。",
  "Proponer": "提議",
  "Proponiendo…": "提議中…",
  "Propuesta sin aceptar": "未接受的提議",
  "Aceptar como canon": "接受為正典",
  "Lo que va entre corchetes lo ha inventado la IA. No es canon hasta que lo aceptes.": "方括號中的內容由AI虛構。在你接受之前，它不屬於正典。",
  "Solo cuenta lo que ya está en la ficha": "只敘述檔案中已有的內容",
  "Rellena los huecos y marca entre corchetes lo que ha inventado": "填補空白，並用方括號標出其虛構的內容",
  "Entrevistar": "訪談",
  "Entrevistar a {name}": "訪談 {name}",
  "Hablar con el personaje en su propia voz": "以角色自己的聲音交談",
  "Responde en su voz y solo sabe lo que hay en su ficha. Nada de esta conversación se guarda.": "以其聲音回答，且只知道其檔案中的內容。此對話不會儲存任何內容。",
  "Responde en su propia voz; las conversaciones se guardan en esta bóveda.": "以其自己的聲音回答；對話會儲存在此知識庫中。",
  "Se eliminará «{title}» junto con todos sus mensajes e imágenes. Esta acción no se puede deshacer.": "將刪除«{title}»及其所有訊息和影像。此操作無法撤銷。",
  "Pregúntale algo.": "向其提問。",
  "Rellena antes su descripción: sin ficha no tiene nada que contestar.": "請先填寫其描述：沒有檔案就沒有可回答的內容。",
  "Tu pregunta…": "你的問題…",
  "Preguntar": "提問",
  "«¿De qué te arrepientes?»": "«你後悔什麼？»",
  "«¿A quién no soportas y por qué?»": "«你受不了誰，為什麼？»",
  "«¿Qué harías si te quitaran lo que más quieres?»": "«如果有人奪走你最愛的東西，你會怎麼做？»",
  "Exportar la ficha a Markdown": "將檔案匯出為 Markdown",
  "Ficha guardada en {path}": "檔案已儲存至 {path}",
  "(sin los nombres secretos ni tus notas privadas)": "（不含秘密名稱和你的私人筆記）",
  "Plantilla": "模板",
  "Solo el nombre. Rellena la ficha a tu manera.": "只有名稱。按你的方式填寫檔案。",
  "Héroe a su pesar": "不情願的英雄",
  "Alguien a quien la trama saca de su vida sin pedirle permiso. Empieza por qué quería en realidad y qué le impide moverse.": "一個被情節不由分說拖離原有生活的人。先寫其真正想要什麼，以及什麼令其止步不前。",
  "Tirano con razones": "有理有據的暴君",
  "Un antagonista que cree estar salvando algo. Lo importante es la mentira que se cree y de dónde salió.": "一個自以為在拯救什麼的對手。重要的是其相信的謊言以及它的來源。",
  "Mentor con secreto": "懷有秘密的導師",
  "Quien enseña y calla lo que más importa. Define qué protege ocultándolo.": "傳授知識卻隱瞞最重要之事的人。定義其通過隱藏所保護的東西。",
  "Embaucador": "騙子",
  "Quien sobrevive hablando y cambia de bando a tiempo. Su voz es media ficha.": "靠言辭生存、及時轉換陣營的人。其聲音就是半份檔案。",
  "Testigo": "目擊者",
  "Un personaje menor que ve lo que nadie más ve. Con poco basta: qué vio y por qué calla.": "一個看到他人所不見之物的次要角色。只需一點：其看到了什麼，以及為何沉默。",
  "Familias": "家族",
  "Dinastías": "王朝",
  "Calendario del mundo": "世界曆法",
  "Definir las eras y los meses de tu mundo": "定義你世界的紀元與月份",
  "Opcional. Sin calendario, el año ordena la cronología igual que hasta ahora; con él, además ordena dentro de cada año y puedes elegir la fecha en vez de escribirla.": "可選。沒有曆法時，年份仍像現在一樣為年表排序；有了它，還能在每年內排序，並且你可以選擇日期而非手動輸入。",
  "Nombre del calendario (opcional)": "曆法名稱（可選）",
  "Guardar calendario": "儲存曆法",
  "Al guardar se recalculan las fechas de todos los hechos ya registrados.": "儲存後，將重新計算所有已記錄事件的日期。",
  "Eras": "紀元",
  "Era": "紀元",
