  "Abreviatura de la era": "紀元縮寫",
  "Año inicial": "起始年份",
  "El «año inicial» es el año absoluto en el que cae el año 1 de esa era: es lo que permite comparar fechas de eras distintas.": "«起始年份»是該紀元第 1 年所處的絕對年份：它使不同紀元的日期可以比較。",
  "Cuenta atrás": "倒計",
  "Cuenta hacia atrás, como «a.C.»": "向後計數，如«西元前»",
  "Sin eras. Puedes usar solo años sueltos.": "無紀元。你可以只使用單獨的年份。",
