  "Ningún lugar coincide con el filtro.": "沒有地點符合篩選條件。",
  "Con el nombre basta. El tipo se sugiere a partir de dónde lo pongas.": "只需名稱即可。型別會根據你放置的位置自動建議。",
  "Atmósfera": "氛圍",
  "Historia": "歷史",
  "Cómo se siente estar ahí.": "身處其中是什麼感覺。",
  "Qué ha pasado aquí antes del relato.": "故事發生之前這裡經歷過什麼。",
  "Arquitectura, materiales, colores, cómo se llega…": "建築、材料、色彩、如何抵達…",
  "Ruidos, olores, quién anda por la calle, qué se teme…": "聲響、氣味、街上都有誰、人們害怕什麼…",
  "Fundación, guerras, quién lo gobernó…": "建立、戰爭、誰曾統治這裡…",
  "Lo que se añade a todas las imágenes para que el lugar se parezca a sí mismo.": "會附加到所有圖片中，使該地點保持自身特色。",
  "p. ej. «ciudad portuaria de piedra gris, tejados de pizarra, niebla»": "例如「灰色石砌港口城市、石板屋頂、霧氣」",
  "Quién está aquí": "誰在這裡",
  "Nadie por ahora. Se añaden desde la ficha del personaje, en sus lugares.": "目前沒有。可從角色檔案的地點中新增。",
  "Un lugar de tipo «{child}» está dentro de uno de tipo «{parent}». ¿Es a propósito?": "一個「{child}」型別的地點位於「{parent}」型別之內。這是故意的嗎？",
  "¿Eliminar este lugar? Los lugares que contiene NO se borran: pasan a estar sueltos.": "刪除此地點？其中包含的地點不會被刪除：它們將變為未放置。",
  "¿Eliminar esta imagen de la galería?": "要從相簿中刪除這張圖片嗎？",
