  "Notas dinásticas": "王朝筆記",
  "Sucesión, ramas, reclamaciones, lemas y legitimidad.": "繼承、分支、宣稱、格言與正統性。",
  "Herederos, ramas cadetes, disputas sucesorias…": "繼承人、旁支、繼承紛爭…",
  "Miembros": "成員",
  "Miembro": "成員",
  "Pertenencias": "歸屬",
  "Añadir pertenencia": "新增歸屬",
  "No pertenece a nada por ahora.": "目前不屬於任何組織。",
  "Crea antes una facción, una cultura o una dinastía.": "請先建立派系、文化或王朝。",
  "Nadie por ahora. Se añaden desde la ficha del personaje, en sus pertenencias.": "目前沒有。可從角色檔案的歸屬中新增。",
  "En una línea": "一句話概括",
  "Lo que dirías de esto en una frase.": "用一句話描述你的看法。",
  "Lo que se ve: emblemas, colores, vestimenta, arquitectura.": "可見的特徵：徽記、色彩、服飾、建築。",
  "Símbolos, atuendo, cómo se reconoce a los suyos…": "符號、裝束、如何辨認其成員…",
  "Lo que se añade a todas las imágenes para que se parezcan entre sí.": "會附加到所有圖片中，使其風格統一。",
  "p. ej. «heráldica de cuervo negro sobre campo gris, plata bruñida»": "例如「灰底黑鴉紋章、拋光銀飾」",
  "p. ej. «los espías de la corte, que ya no responden ante nadie»": "例如「宮廷密探，已不再聽命於任何人」",
  "{from} → {to}": "{from} → {to}",
  "¿Eliminar esto? Los personajes NO se borran: solo dejan de pertenecer.": "要刪除嗎？角色不會被刪除：只是不再屬於該組織。",
  "Nueva escena": "新建場景",
  "Crear escena": "建立場景",
  "Eliminar escena": "刪除場景",
  "Buscar escenas…": "搜尋場景…",
  "Título de la escena": "場景標題",
  "Volver a las escenas": "返回場景列表",
  "Todavía no hay escenas en este mundo.": "這個世界還沒有場景。",
  "Ninguna escena coincide con el filtro.": "沒有場景符合篩選條件。",
  "Se añade al final del relato; puedes moverla después.": "會新增到敘事末尾；之後可以移動。",
  "Esbozo": "大綱",
  "Escrita": "已撰寫",
  "Orden en el relato": "敘事順序",
  "Sin lugar": "無地點",
  "Qué pasa": "發生了什麼",
  "Lo que ocurre en la escena, en tus palabras.": "用你自己的話描述場景中發生的事。",
  "Quién quiere qué, quién se lo impide y cómo acaba…": "誰想要什麼、誰從中阻撓，以及結局如何…",
  "Quién aparece": "登場人物",
  "Añadir personaje a la escena": "向場景新增角色",
  "Crea antes algún personaje.": "請先建立角色。",
  "¿Eliminar esta escena? Los personajes que aparecen en ella NO se borran.": "刪除此場景？其中登場的角色不會被刪除。",
  "El año es cuándo ocurre en el mundo; el orden es dónde va en el relato. Un prólogo ambientado siglos antes va primero en el relato y último en la cronología.": "年份是它在該世界中發生的時間；順序是它在敘事中的位置。設定在幾個世紀前的序章在敘事中排在最前，在時間線上排在最後。",
  "Apariciones": "登場",
  "En orden del relato, no de la cronología.": "按敘事順序，而非時間線順序。",
  "Secretos": "秘密",
  "Añadir secreto": "新增秘密",
  "Qué esconde…": "隱藏著什麼…",
  "No esconde nada por ahora.": "目前沒有隱藏任何事。",
  "Revelado": "已揭曉",
  "Además sabe": "還知道",
  "Diseña unidades para el docente o apuntes para entregar al alumnado, siempre desde tus fuentes.": "為教師設計教學單元，或為學生準備講義，始終基於你的資料。",
  "Elige si necesitas una planificación para impartir la lección o apuntes listos para entregar.": "選擇你需要授課用的教案，還是可直接分發的講義。",
  "Elige si necesitas apuntes para aprender o una planificación para enseñar el tema.": "選擇你需要用於學習的筆記，還是用於講授該主題的教案。",
  "Escribe el tema o la lección que quieres preparar. El informe diseñará objetivos, secuencia, actividades y evaluación usando tus materiales.": "輸入你想準備的主題或課程。報告將使用你的材料設計目標、序列、活動和評估。",
  "Escribe el tema de los apuntes. El informe lo explicará paso a paso con ejemplos y autoevaluación usando tus materiales.": "輸入筆記的主題。報告將使用你的材料，通過示例和自測逐步講解。",
  "Público objetivo y producto": "目標受眾與產出",
  "Docente · planificación de la lección": "教師 · 教案",
  "Alumnado · apuntes para entregar": "學生 · 分發講義",
  "Generará objetivos, secuencia, actividades, comprobaciones de comprensión y evaluación para el docente.": "將為教師生成目標、序列、活動、理解檢驗和評估。",
  "Generará explicaciones, definiciones, ejemplos, síntesis y autoevaluación dirigidos al alumnado.": "將為學生生成講解、定義、示例、綜述和自測。",
  "En «Crear», Unidades didácticas ya permite generar una planificación para el docente o apuntes para el alumnado a partir de tus materiales. Las demás secciones punteadas siguen abiertas a tus sugerencias. Puedes repetir este tutorial desde Ajustes.": "在「建立」中，「教學單元」現已支援根據你的材料為教師生成教案或為學生生成講義。其餘虛線標記的部分仍歡迎你的建議。你可以從「設定」中重播本教程。",
