  "Esta entrada todavía no existe": "此條目尚不存在",
  "Crear la entrada «{name}»": "建立條目「{name}」",
  "Los artículos son para lo que no es un personaje, un lugar ni una facción: la magia, una religión, una lengua, una criatura, un objeto. Todo lo demás ya está en la enciclopedia por sí solo.": "文章用於角色、地點或派系之外的內容：魔法、宗教、語言、生物、物品。其餘內容已自動收錄在百科中。",
  "Nuevo artículo": "新建文章",
  "Todavía nadie ha definido esto. Al crearlo, todas las menciones que lo esperaban quedarán enlazadas.": "還沒有人定義過它。建立後，所有等待它的提及都會建立連結。",
  "Escribe [[ para enlazar con cualquier cosa del mundo": "輸入 [[ 即可連結世界中的任何內容",
  "Escribe la entrada…": "輸入條目內容…",
  "Creada y enlazada.": "已建立並連結。",
  "Creada. {count} menciones enlazadas.": "已建立。已連結{count}處提及。",
  "Eliminar la entrada": "刪除條目",
  "Escribiendo…": "正在寫入…",
  "Esta ficha aún no tiene texto. Se escribe en su propia sección.": "此檔案還沒有文本。可在其專屬部分中撰寫。",
  "Ficha completa": "完整檔案",
  "Las menciones que la enlazaban no se borran: quedarán marcadas como pendientes.": "連結到它的提及不會被刪除：它們會被標記為待處理。",
  "Mencionada en": "提及於",
  "No hay bastante material todavía: escribe un resumen o enlaza algo.": "材料還不夠：請撰寫摘要或連結一些內容。",
