  "Nodus Browser no abre este tipo de dirección": "Nodus Browser 不開啟此類地址",
  "Esta página dejó de responder": "此頁面停止響應",
  "Ojo: si entras en tu navegador, la sesión se queda allí. Seguirás sin haber iniciado sesión en {host} dentro de Nodus, porque las cookies no se comparten entre navegadores.": "注意：如果你在自己的瀏覽器中登入，會話會留在那裡。在 Nodus 內你仍處於未登入 {host} 的狀態，因為 Cookie 不會在瀏覽器之間共享。",
  "Ojo: si entras en tu navegador, la sesión se queda allí. Seguirás sin haber iniciado sesión en Google dentro de Nodus, porque las cookies no se comparten entre navegadores.": "注意：如果你在自己的瀏覽器中登入，會話會留在那裡。在 Nodus 內你仍處於未登入 Google 的狀態，因為 Cookie 不會在瀏覽器之間共享。",
  "Si {host} admite entrar con contraseña o con un enlace por correo, esa vía sí funciona aquí dentro, y Nodus recordará la sesión.": "如果 {host} 支援使用密碼或郵件連結登入，該方式在這裡確實可用，Nodus 會記住會話。",
  "Volver e intentar con contraseña": "返回並嘗試使用密碼",
  "Usar {host} en mi navegador": "在我的瀏覽器中使用 {host}",
  "Para que Nodus lea tu Gmail o tu Drive haría falta otra cosa: conectar la cuenta desde Ajustes, que es la vía que Google sí admite para aplicaciones de escritorio. Todavía no está disponible.": "要讓 Nodus 讀取你的 Gmail 或 Drive 還需要另一種方式：從設定中連線帳戶，這是 Google 確實允許桌面應用採用的途徑。目前尚不可用。",
  "No es un fallo de Nodus: Google rechaza el inicio de sesión desde cualquier navegador incrustado en otra aplicación.": "這不是 Nodus 的故障：Google 拒絕從任何嵌入其他應用的瀏覽器登入。",
  "Google no permite iniciar sesión desde un navegador integrado": "Google 不允許從嵌入式瀏覽器登入",
  "Abrir en tu navegador": "在你的瀏覽器中開啟",
