  "La conexión con este sitio no es privada": "與此網站的連線不是私密的",
  "Chromium no pudo verificar que «{host}» sea quien dice ser. Puede tratarse de un certificado caducado o mal configurado, o de que alguien esté interceptando la conexión.": "Chromium 無法驗證「{host}」的身份。可能是證書已過期或配置錯誤，也可能有人正在攔截該連線。",
  "Nodus Browser no ofrece continuar de todos modos: no valida certificados por su cuenta, así que no puede contradecir ese veredicto.": "Nodus Browser 不提供「仍然繼續」的選項：它不自行驗證證書，因此無法推翻該判定。",
