  "Borrar las cookies cerrará tu sesión en los sitios donde la tengas iniciada.": "刪除 Cookie 會使你從已登入的網站退出。",
  "También se cerrarán todas las pestañas abiertas del navegador.": "所有已開啟的瀏覽器標籤頁也將關閉。",
  "Chromium borra las cookies por dominio registrable: al borrar las de un subdominio se borran también las del dominio principal y sus demás subdominios.": "Chromium 按可註冊域刪除 Cookie：刪除某個子域的 Cookie 時，也會刪除主域及其其他子域的 Cookie。",
  "Nodus puede medir la caché y el tamaño total del perfil. Chromium no informa del tamaño de cada categoría de almacenamiento por separado, así que las demás se muestran por número de sitios afectados.": "Nodus 可以測量快取和配置檔案總大小。Chromium 不會單獨報告各儲存類別的大小，因此其餘類別按受影響的網站數量顯示。",
  "Nodus Browser conserva cookies y almacenamiento de sitio para que sigas con la sesión iniciada donde corresponda. Nodus no guarda usuarios ni contraseñas, y no incluye gestor de contraseñas.": "Nodus Browser 保留 Cookie 和網站儲存，以便你在相應網站保持登入。Nodus 不儲存使用者名稱和密碼，也不包含密碼管理器。",
