  "Copias previas a migraciones": "遷移前副本",
  "Antes de cambiar el esquema, Nodus conserva una copia inmutable y verificada. Puedes abrirla como un vault separado sin sustituir el actual.": "在更改架構之前，Nodus 會保留一份不可變且經過驗證的副本。你可以將其作為獨立知識庫開啟，而不會替換當前知識庫。",
  "La copia previa se abrió como un vault separado.": "遷移前副本已作為獨立知識庫開啟。",
