  "Coordina la edición del volumen; las ideas no se le atribuyen.": "負責協調該卷的編輯；其觀點不歸屬於此人。",
  "Excepción: los marcados no registran ningún autor, así que sus ideas se muestran aquí de forma provisional.": "例外：被標記的文獻未記錄任何作者，因此其觀點在此暫定顯示。",
  "Esta obra no registra ningún autor: sus ideas se atribuyen provisionalmente a quien la edita": "此文獻未記錄任何作者：其觀點暫定歸屬於編輯它的人",
