  "El texto disponible ha cambiado. Se conserva el análisis anterior hasta completar un reescaneo.": "可用文本已發生變化。在完成重新掃描之前，保留先前的分析。",
  "El adjunto existe en Zotero, pero el archivo ya no está en su ubicación original.": "附件存在於 Zotero 中，但檔案已不在其原始位置。",
  "El PDF está escaneado y no tiene capa de texto. Activa OCR y vuelve a analizar.": "該 PDF 為掃描件，沒有文本層。請啟用 OCR 並重新分析。",
