  "Incluye metadatos, extractos y análisis; nunca archivos originales, rutas locales ni datos privados.": "包含後設資料、摘錄和分析；絕不包含原始檔案、本地路徑或私有資料。",
  "Publicar testimonios textuales": "釋出文本證詞",
  "Incluye entrevistas, transcripciones y análisis; participantes, acuerdos y archivos multimedia permanecen privados.": "包含訪談、轉錄和分析；參與者、協議和媒體檔案保持私密。",
  "notas, borradores y organización": "筆記、草稿與組織",
  "Organiza notas, borradores y materiales en un único espacio con citas verificables.": "在單一空間中整理筆記、草稿和材料，並附可驗證的引注。",
  "Organiza el trabajo del corpus": "整理語料庫工作",
  "Ya hay suficientes ideas y fuentes para organizar notas y borradores con citas verificables en un único espacio de trabajo.": "已有足夠的觀點和資料，可以在單一工作空間中整理帶有可驗證引注的筆記和草稿。",
  "Abrir espacio de trabajo": "開啟工作空間",
