  "El Espacio de trabajo reúne notas, borradores y organización en una única superficie. Conserva las citas clicables y permite estructurar el manuscrito sin separar artificialmente Escritura y Proyectos.": "工作空間將筆記、草稿和組織彙集於同一介面。它保留可點選的引注，並讓你組織手稿，而無需人為地分隔寫作與專案。",
